/* Card set: Motorcycles (generated from the approved roster-final.csv by the Motorcycles build, schema per tools/csv-to-set.js).
   (motorcycles.js exceeds the comfortable push size, so the remaining cards live in
   motorcycles-additions.js, which must stay directly after 'motorcycles.js' in sets/manifest.js.) */
CardSets.register({"id":"motorcycles","name":"Motorcycles","code":"MOTO","description":"420 cards of two-wheeled icons — American cruisers, British and European classics, Japanese sport bikes, dirt and adventure machines, scooters, screen-famous bikes and the pioneers that started it all.","theme":{"primary":"#a63d21","secondary":"#2e4a5a","artBackground":"#f4efe8","artFit":"cover"},"pack":{"name":"Motorcycles Pack","emblem":"🏍️","skin":"motorcycles"},"cards":[{"name":"Honda CB750","rarity":"chase","id":"honda-cb750","subtitle":"Japanese Sport & Standards","details":"Debuting in 1969 with an inline-four, disc brake and electric start, the CB750 defined the superbike and changed motorcycling worldwide.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/HONDA_CB_750_Four%3B_Germany%2C_1971.jpg/1280px-HONDA_CB_750_Four%3B_Germany%2C_1971.jpg"},{"name":"Triumph Bonneville T120","rarity":"chase","id":"triumph-bonneville-t120","subtitle":"British & European Classics","details":"The twin-carburettor flagship of Meriden's twin range, the T120 paired 649cc parallel-twin pace with timeless styling that defined an era.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/Triumph_Bonneville_T120_%281970%29_-_8962027645.jpg/960px-Triumph_Bonneville_T120_%281970%29_-_8962027645.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Harley-Davidson Knucklehead","rarity":"chase","id":"harley-davidson-knucklehead","subtitle":"American Cruisers","details":"Harley's 1936 EL overhead-valve V-twin earned its name from rocker covers shaped like knuckles and became the template for every big twin after it.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Harley-Davidson_Museum_December_2023_46_%281936_EL--OHV_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_December_2023_46_%281936_EL--OHV_V-Twin%29.jpg"},{"name":"Indian Chief","rarity":"chase","id":"indian-chief","subtitle":"American Cruisers","details":"The 1940s Chief wore deep skirted fenders, a sprung saddle and Indian's hand-shift V-twin, becoming the most recognizable American motorcycle of its era.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/1947_Indian_Chief_Blackhawk_%2827149367148%29.jpg/1280px-1947_Indian_Chief_Blackhawk_%2827149367148%29.jpg"},{"name":"Ducati 916","rarity":"chase","id":"ducati-916","subtitle":"British & European Classics","details":"Massimo Tamburini's masterpiece paired a 916cc desmoquattro V-twin with a single-sided swingarm and under-seat exhausts in a trellis frame.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Ducati_916.jpg/960px-Ducati_916.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BMW R32","rarity":"chase","id":"bmw-r32","subtitle":"Historic Pioneers","details":"BMW's first motorcycle, launched in 1923, paired a 494cc flat-twin with shaft drive - a layout that defined the brand's machines for decades.","image":"https://upload.wikimedia.org/wikipedia/commons/0/02/1923_BMW_R32_%281%29_-_The_Art_of_the_Motorcycle_-_Memphis.jpg"},{"name":"Norton Commando","rarity":"chase","id":"norton-commando","subtitle":"British & European Classics","details":"Launched for 1968, the Commando used rubber Isolastic mounts to tame its 745cc twin's vibration and became Norton's definitive roadster.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/Norton_Commando_850_Roadster_%281975%29.jpg/960px-Norton_Commando_850_Roadster_%281975%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Kawasaki Z1","rarity":"chase","id":"kawasaki-z1","subtitle":"Japanese Sport & Standards","details":"The 903cc Z1 of 1972 out-muscled every rival with its double-overhead-cam four, earning a fearsome reputation for speed and strength.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3b/Kawasaki_900_Z1.JPG"},{"name":"Suzuki Hayabusa","rarity":"chase","id":"suzuki-hayabusa","subtitle":"Japanese Sport & Standards","details":"The 1999 Hayabusa's sleek aero body and 1299cc four made it famed for the top-speed rivalry of the late 1990s and its effortless pace.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1c/Suzuki_Hayabusa_1300.jpg"},{"name":"Vespa 150 GS","rarity":"chase","id":"vespa-150-gs","subtitle":"Scooters, Minis & Oddballs","details":"Piaggio's 1950s flagship, the GS paired a 150cc two-stroke with a four-speed gearbox and 10-inch wheels, becoming the definitive sporting Vespa.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Piaggio_Vespa_150_GS_1960b.JPG/960px-Piaggio_Vespa_150_GS_1960b.JPG"},{"name":"Harley-Davidson Panhead","rarity":"legendary","id":"harley-davidson-panhead","subtitle":"American Cruisers","details":"The 1948 FL Panhead replaced the Knucklehead with aluminum heads and hydraulic lifters, its shallow rocker covers giving the engine its kitchen-pan name.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/1949_Harley_Davidson_Panhead_%286842568929%29.jpg/1280px-1949_Harley_Davidson_Panhead_%286842568929%29.jpg"},{"name":"Harley-Davidson Fat Boy","rarity":"legendary","id":"harley-davidson-fat-boy","subtitle":"American Cruisers","details":"The 1990 FLSTF Fat Boy paired solid disc wheels with a shotgun stance, and a silver original became one of the best-known Harleys ever built.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Harley-Davidson_Museum_May_2024_17_%281990_FLSTF_Fat_Boy--OHV_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_May_2024_17_%281990_FLSTF_Fat_Boy--OHV_V-Twin%29.jpg"},{"name":"Indian Roadmaster","rarity":"legendary","id":"indian-roadmaster","subtitle":"American Cruisers","details":"Indian's Roadmaster is a full-dress tourer with a fork-mounted fairing, hard lower fairings and a top trunk, powered by the Thunder Stroke V-twin.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Indian_Roadmaster%40Motodays_2017_07.jpg/1280px-Indian_Roadmaster%40Motodays_2017_07.jpg"},{"name":"Indian Chieftain","rarity":"legendary","id":"indian-chieftain","subtitle":"American Cruisers","details":"Indian's 2014 Chieftain revived a nameplate from 1946 as a fork-faired touring bagger powered by the air-cooled Thunder Stroke 111 V-twin.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/Indian_Chieftain_parked_at_Hogs_for_Hospice%2C_Leamington%2C_Ontario%2C_2025-08-02.jpg/1280px-Indian_Chieftain_parked_at_Hogs_for_Hospice%2C_Leamington%2C_Ontario%2C_2025-08-02.jpg"},{"name":"Harley-Davidson V-Rod","rarity":"legendary","id":"harley-davidson-v-rod","subtitle":"American Cruisers","details":"The 2002 VRSC V-Rod broke Harley tradition with a liquid-cooled Revolution V-twin developed with Porsche, hidden under a drag-bike silhouette.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Harley-Davidson_VRSCA_V-Rod.JPG/1280px-Harley-Davidson_VRSCA_V-Rod.JPG"},{"name":"Vincent Black Shadow","rarity":"legendary","id":"vincent-black-shadow","subtitle":"British & European Classics","details":"Philip Vincent's 998cc V-twin was built to exceptional standards in Stevenage, and Series C Shadows are famed for their huge 150mph speedometer.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Vincent_Black_Shadow_%286390803421%29.jpg/960px-Vincent_Black_Shadow_%286390803421%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Vincent Rapide","rarity":"legendary","id":"vincent-rapide","subtitle":"British & European Classics","details":"Vincent's 998cc V-twin Rapide was the fast touring half of the Stevenage range, a hand-built machine of rare speed and finish for its day.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Vincent_1949_Series_C_Rapide_%288229887302%29.jpg/960px-Vincent_1949_Series_C_Rapide_%288229887302%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"MV Agusta 750 S","rarity":"legendary","id":"mv-agusta-750-s","subtitle":"British & European Classics","details":"Derived from MV's Grand Prix machinery, the shaft-drive 750 S four wore drum brakes, a sculpted tank and racing red, white and blue paint.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/MV_Agusta_750S_01.jpg/960px-MV_Agusta_750S_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BMW R90S","rarity":"legendary","id":"bmw-r90s","subtitle":"British & European Classics","details":"BMW's 1973 flagship sportster wore a bikini fairing, Dell'Orto carburettors and smoked two-tone paint, and won the first AMA Superbike title.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/BMW_R90S_gold_1975_r_TCE.jpg/960px-BMW_R90S_gold_1975_r_TCE.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Moto Guzzi 850 Le Mans","rarity":"legendary","id":"moto-guzzi-850-le-mans","subtitle":"British & European Classics","details":"Guzzi's flagship cafe racer linked its 844cc V-twin's cylinder heads to low clip-ons, a bikini fairing and cast wheels in vivid racing colours.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Moto_Guzzi_850_Le_Mans_%281976%29_-_19652077549.jpg/960px-Moto_Guzzi_850_Le_Mans_%281976%29_-_19652077549.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Honda CBX","rarity":"legendary","id":"honda-cbx","subtitle":"Japanese Sport & Standards","details":"Honda's CBX carried a 1047cc air-cooled inline-six with 24 valves, a flagship famed for smoothness, width and a spine-tingling exhaust howl.","image":"https://upload.wikimedia.org/wikipedia/commons/0/03/CBX_1000_arg.jpg"},{"name":"Yamaha RD350","rarity":"legendary","id":"yamaha-rd350","subtitle":"Japanese Sport & Standards","details":"The RD350's air-cooled two-stroke twin gave giant-killing pace in a light chassis, making it the era's definitive wheelie-happy sportsbike.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Yamaha_RD350_maroon.jpg/1280px-Yamaha_RD350_maroon.jpg"},{"name":"Kawasaki GPZ900R","rarity":"legendary","id":"kawasaki-gpz900r","subtitle":"Japanese Sport & Standards","details":"The GPZ900R Ninja's liquid-cooled 908cc four set the superbike template of the mid-1980s, its engine serving as a stressed frame member.","image":"https://upload.wikimedia.org/wikipedia/commons/5/54/Kawasaki_GPZ900R_Ninja_01.jpg"},{"name":"Suzuki GSX-R750","rarity":"legendary","id":"suzuki-gsx-r750","subtitle":"Japanese Sport & Standards","details":"The 1985 GSX-R750 brought race-bred aluminium framing and an oil-cooled four to the street, launching the modern replica-racer superbike class.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Suzuki_GSX-R750.JPG/1280px-Suzuki_GSX-R750.JPG"},{"name":"Honda RC30","rarity":"legendary","id":"honda-rc30","subtitle":"Japanese Sport & Standards","details":"Honda's VFR750R, the RC30, was a hand-built homologation special with a V4, gear-driven cams and a single-sided swingarm made for endurance racing.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Honda_VFR750R_RC30.JPG/1280px-Honda_VFR750R_RC30.JPG"},{"name":"Yamaha V-Max","rarity":"legendary","id":"yamaha-v-max","subtitle":"Japanese Sport & Standards","details":"The original V-Max was a power cruiser icon, its 1198cc V4 and V-Boost intake serving dragstrip muscle in a streetfighter stance.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/YAMAHA_Vmax.jpg/1280px-YAMAHA_Vmax.jpg"},{"name":"Honda CRF1000L Africa Twin","rarity":"legendary","id":"honda-crf1000l-africa-twin","subtitle":"Dirt, Adventure & Off-Road","details":"Honda revived the Africa Twin name with this 998cc adventure flagship, honoring its Paris-Dakar racers with long-range touring and off-road ability.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Honda_CRF1000L_front-left_2016_Auto_China.jpg/1280px-Honda_CRF1000L_front-left_2016_Auto_China.jpg"},{"name":"BMW R 1200 GS","rarity":"legendary","id":"bmw-r-1200-gs","subtitle":"Dirt, Adventure & Off-Road","details":"BMW's big boxer GS defined the adventure-touring class, pairing a 1,170cc flat twin with Telelever front suspension and shaft drive.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8d/1200gsfr.jpg"},{"name":"KTM 990 Adventure","rarity":"legendary","id":"ktm-990-adventure","subtitle":"Dirt, Adventure & Off-Road","details":"KTM's 990 Adventure carried the LC8 75-degree V-twin from its Dakar program into a tall, dirt-ready travel bike with genuine rally pedigree.","image":"https://upload.wikimedia.org/wikipedia/commons/5/57/KTM_990_Adventure_S.jpg"},{"name":"Yamaha XT500","rarity":"legendary","id":"yamaha-xt500","subtitle":"Dirt, Adventure & Off-Road","details":"Yamaha's XT500 was a 499cc four-stroke single trail bike whose torquey thumper layout helped launch the modern dual-sport era in the late 1970s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/1976_Yamaha_XT500.JPG/1280px-1976_Yamaha_XT500.JPG"},{"name":"Honda Super Cub","rarity":"legendary","id":"honda-super-cub","subtitle":"Scooters, Minis & Oddballs","details":"Honda's step-through Cub is the best-selling motor vehicle in history, its total passing 100 million as riders worldwide adopted the simple design.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Honda_super_cub%2C_1st_Gen._1958%2C_Left_side.jpg/960px-Honda_super_cub%2C_1st_Gen._1958%2C_Left_side.jpg"},{"name":"Lambretta GP 200","rarity":"legendary","id":"lambretta-gp-200","subtitle":"Scooters, Minis & Oddballs","details":"Innocenti's GP200 topped the Lambretta range with a 200cc two-stroke and a front disc brake, making it the quickest production Lambretta of its era.","image":"https://upload.wikimedia.org/wikipedia/commons/8/80/GP200.jpg"},{"name":"Easy Rider Captain America Chopper","rarity":"legendary","id":"captain-america-chopper","subtitle":"Famous & Movie Bikes","details":"Peter Fonda rides this stars-and-stripes Harley chopper across America in Easy Rider, the 1969 film that defined the biker movie for generations.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Harley-Davidson_Museum_Easy_Rider_Captain_America_Bike.JPG/1280px-Harley-Davidson_Museum_Easy_Rider_Captain_America_Bike.JPG"},{"name":"The Great Escape Triumph TR6","rarity":"legendary","id":"great-escape-triumph-tr6","subtitle":"Famous & Movie Bikes","details":"Disguised as a German army bike, this Triumph TR6 carried Steve McQueen toward the wire in The Great Escape, with Bud Ekins making the famous jump.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/The_Great_Escape_Jump.jpg/1280px-The_Great_Escape_Jump.jpg"},{"name":"Terminator 2 Harley Fat Boy","rarity":"legendary","id":"terminator-2-fat-boy","subtitle":"Famous & Movie Bikes","details":"Arnold Schwarzenegger's T-800 rides this black 1990 Harley-Davidson Fat Boy through the LA flood channels in Terminator 2: Judgment Day.","image":"https://cdn-fastly.motorcycle.com/media/2023/05/31/11600443/terminator-2-harley-davidson-is-coming-home.jpg?size=1200x800"},{"name":"The Wild One Triumph Thunderbird","rarity":"legendary","id":"wild-one-triumph-thunderbird","subtitle":"Famous & Movie Bikes","details":"Marlon Brando's Johnny Strabler rides this Triumph Thunderbird 6T in The Wild One, the 1953 outlaw biker film that started a cultural panic and a legend.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Triumph_Thunderbird_from_the_movie_%22The_Wild_One%22_%281953%29.jpg/1280px-Triumph_Thunderbird_from_the_movie_%22The_Wild_One%22_%281953%29.jpg"},{"name":"Brough Superior SS100","rarity":"legendary","id":"brough-superior-ss100","subtitle":"Historic Pioneers","details":"Built in Nottingham from 1924, every SS100 was tested at 100 mph before delivery; T. E. Lawrence owned several of these hand-built V-twins.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Hochgurgl-Top_Mountain_Motorcycle_Museum-Brough_Superior_SS100-1925-1000ccm-03ESD.jpg/1280px-Hochgurgl-Top_Mountain_Motorcycle_Museum-Brough_Superior_SS100-1925-1000ccm-03ESD.jpg"},{"name":"Daimler Reitwagen","rarity":"legendary","id":"daimler-reitwagen","subtitle":"Historic Pioneers","details":"Gottlieb Daimler's 1885 wooden 'riding car' ran a petroleum single with outrigger wheels, a test bed for the engine that changed transport.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/Daimler_Reitwagen_Nachbau.jpg/1280px-Daimler_Reitwagen_Nachbau.jpg"},{"name":"Curtiss V-8","rarity":"legendary","id":"curtiss-v8","subtitle":"Historic Pioneers","details":"Glenn Curtiss put an airship V-8 in a motorcycle frame in 1907 and reached 136 mph at Ormond Beach, becoming the 'fastest man on earth'.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Curtiss_V-8_Motorcycle.jpg/1280px-Curtiss_V-8_Motorcycle.jpg"},{"name":"Flying Merkel","rarity":"legendary","id":"flying-merkel","subtitle":"Historic Pioneers","details":"With a sprung frame at both ends and bright orange paint, the Flying Merkel V-twin was among the most advanced American motorcycles of its era.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/The_flying_Merkel_%2840006891483%29.jpg/1280px-The_flying_Merkel_%2840006891483%29.jpg"},{"name":"Harley-Davidson Shovelhead","rarity":"epic","id":"harley-davidson-shovelhead","subtitle":"American Cruisers","details":"The Shovelhead big twin of 1966 to 1984 took its name from shovel-shaped rocker boxes and carried Harley through the AMF years into the Evolution era.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6d/Harley_Davidson_FLH_1970_ElectraGlide_RSideFront_Lake_Mirror_Cassic_16Oct2010_%2814854237346%29.jpg"},{"name":"Harley-Davidson Sportster Ironhead","rarity":"epic","id":"harley-davidson-sportster-ironhead","subtitle":"American Cruisers","details":"Ironhead Sportsters of 1957 to 1985 ran cast-iron heads on a unit-construction 900 and 1000cc twin, earning a raw, mechanical cult following.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/1957_Harley-Davidson_XL_Sportster.jpg/1280px-1957_Harley-Davidson_XL_Sportster.jpg"},{"name":"Harley-Davidson Electra Glide","rarity":"epic","id":"harley-davidson-electra-glide","subtitle":"American Cruisers","details":"The Electra Glide name arrived in 1965 with electric starting on the last Panhead, then became Harley's long-running full-dress touring flagship.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Harley_Davidson_FLHT_Electra_Glide.jpg/1280px-Harley_Davidson_FLHT_Electra_Glide.jpg"},{"name":"Harley-Davidson Road King","rarity":"epic","id":"harley-davidson-road-king","subtitle":"American Cruisers","details":"The Road King blends a detachable windshield and hard saddlebags with stripped-down cruiser styling, a touring bike built around a big nacelle headlamp.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Harley-Davidson_1450_Road_King.JPG/1280px-Harley-Davidson_1450_Road_King.JPG"},{"name":"Harley-Davidson Street Glide","rarity":"epic","id":"harley-davidson-street-glide","subtitle":"American Cruisers","details":"The Street Glide is Harley's slammed factory bagger, defined by its fork-mounted batwing fairing, low rear end and stripped touring equipment.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Paris_-_Salon_de_la_moto_2011_-_Harley-Davidson_-_FLHX_Street_Glide_-_001.jpg/1280px-Paris_-_Salon_de_la_moto_2011_-_Harley-Davidson_-_FLHX_Street_Glide_-_001.jpg"},{"name":"Victory Cross Country","rarity":"epic","id":"victory-cross-country","subtitle":"American Cruisers","details":"Victory's Cross Country was a full touring bagger built on an aluminum frame, with an inverted fork and the air-cooled Freedom 106 V-twin.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Paris_-_Salon_de_la_moto_2011_-_Victory_-_Cross_Country_Tour_-_001.jpg/1280px-Paris_-_Salon_de_la_moto_2011_-_Victory_-_Cross_Country_Tour_-_001.jpg"},{"name":"Harley-Davidson Low Rider","rarity":"epic","id":"harley-davidson-low-rider","subtitle":"American Cruisers","details":"The 1977 FXS Low Rider launched the factory custom idea: a lowered Super Glide with mag wheels, drag bars and a stepped seat straight from the showroom.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/Harley-Davidson_Low_Rider_%2817149269014%29.jpg/1280px-Harley-Davidson_Low_Rider_%2817149269014%29.jpg"},{"name":"Indian Springfield","rarity":"epic","id":"indian-springfield","subtitle":"American Cruisers","details":"The Springfield pairs valanced fenders and a quick-release windshield with hard saddlebags, blending classic Indian dress with modern touring manners.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Indian_Springfield_parked_along_North_Street%2C_Dresden%2C_Ontario%2C_2025-09-13.jpg/1280px-Indian_Springfield_parked_along_North_Street%2C_Dresden%2C_Ontario%2C_2025-09-13.jpg"},{"name":"BSA Gold Star","rarity":"epic","id":"bsa-gold-star","subtitle":"British & European Classics","details":"The DBD34 Gold Star was a hand-assembled 500cc single tuned at the factory, famous for its close-ratio gearbox and Brooklands heritage.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Flickr_-_ronsaunders47_-_BSA_GOLD_STAR-500_CC_SINGLE..jpg/960px-Flickr_-_ronsaunders47_-_BSA_GOLD_STAR-500_CC_SINGLE..jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Triumph Trident T150","rarity":"epic","id":"triumph-trident-t150","subtitle":"British & European Classics","details":"Meriden's 741cc triple answered the Honda CB750 with three cylinders, five gears in later form, and a distinctive, eager exhaust note.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Triumph_Trident_T150_%281969%29_-_14499517602.jpg/960px-Triumph_Trident_T150_%281969%29_-_14499517602.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BMW R100RS","rarity":"epic","id":"bmw-r100rs","subtitle":"British & European Classics","details":"Styled in BMW's own wind tunnel, the R100RS of 1976 set the template for the modern sports tourer with its fixed full fairing and 980cc boxer twin.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/BMW_R-100-RS_in_BMW-Museum-Munich_%28cropped%29.JPG/960px-BMW_R-100-RS_in_BMW-Museum-Munich_%28cropped%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Laverda 1000 Jota","rarity":"epic","id":"laverda-1000-jota","subtitle":"British & European Classics","details":"Slater Brothers' tuned version of Laverda's 981cc triple, the Jota used high-lift cams and loud pipes to become a byword for raw speed.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Laverda_Jota_1000_%281981%29_-_15672929907.jpg/960px-Laverda_Jota_1000_%281981%29_-_15672929907.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Benelli 750 Sei","rarity":"epic","id":"benelli-750-sei","subtitle":"British & European Classics","details":"The 750 Sei was the first production motorcycle with a six-cylinder engine, its 747cc six breathing through a thicket of chrome exhaust pipework.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Benelli_750_Sei_%281975%29.jpg/960px-Benelli_750_Sei_%281975%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Velocette Thruxton","rarity":"epic","id":"velocette-thruxton","subtitle":"British & European Classics","details":"The Venom Thruxton's 499cc single used a close-ratio gearbox, rear-set footrests and a swept megaphone to win at its namesake circuit.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Flickr_-_ronsaunders47_-_VELOCETTE_THRUXTON._500cc_FOUR_STROKE_SINGLE..jpg/960px-Flickr_-_ronsaunders47_-_VELOCETTE_THRUXTON._500cc_FOUR_STROKE_SINGLE..jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ducati 750 Super Sport","rarity":"epic","id":"ducati-750-super-sport","subtitle":"British & European Classics","details":"Built to honour Paul Smart's 1972 Imola victory, the bevel-drive 750 Super Sport was Ducati's first desmo V-twin production superbike.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/1975_Ducati_750_Super_Sport_Desmo.jpg/960px-1975_Ducati_750_Super_Sport_Desmo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Moto Guzzi V7 Sport","rarity":"epic","id":"moto-guzzi-v7-sport","subtitle":"British & European Classics","details":"Lino Tonti's V7 Sport framed Guzzi's 748cc V-twin in a low cradle chassis with swan-neck clip-ons, creating the definitive Italian sports bike.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Moto_Guzzi_V7_Sport_Telaio_Rosso_750cc_1971_a.jpg/960px-Moto_Guzzi_V7_Sport_Telaio_Rosso_750cc_1971_a.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Honda CBR900RR FireBlade","rarity":"epic","id":"honda-cbr900rr-fireblade","subtitle":"Japanese Sport & Standards","details":"The 1992 FireBlade paired near-900cc power with 600-class weight, a Tadao Baba formula that reset superbike priorities toward agility.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Honda_CBR900RR_Fireblade_1992_cropped.jpg/1280px-Honda_CBR900RR_Fireblade_1992_cropped.jpg"},{"name":"Yamaha YZF-R1","rarity":"epic","id":"yamaha-yzf-r1","subtitle":"Japanese Sport & Standards","details":"The 1998 YZF-R1 stacked its gearbox shafts to shrink the engine, wrapping race-bred power in a compact chassis that redefined the litre superbike.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/1998_Yamaha_YZF-R1_in_the_Yamaha_Communication_Plaza.JPG/1280px-1998_Yamaha_YZF-R1_in_the_Yamaha_Communication_Plaza.JPG"},{"name":"Kawasaki H2 Mach IV","rarity":"epic","id":"kawasaki-h2-mach-iv","subtitle":"Japanese Sport & Standards","details":"The 748cc two-stroke triple H2 earned its 'widowmaker' legend from fierce acceleration, a flexible frame and minimal brakes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Kawasaki_H2_Mach_IV_%283%29.jpg/1280px-Kawasaki_H2_Mach_IV_%283%29.jpg"},{"name":"Suzuki GSX1100S Katana","rarity":"epic","id":"suzuki-gsx1100s-katana","subtitle":"Japanese Sport & Standards","details":"Styled by Target Design, the 1981 Katana's sharp origami bodywork and 16-valve four made it one of the most distinctive superbikes ever built.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Suzuki_GSX-1100S_Katana_noBG.jpg/1280px-Suzuki_GSX-1100S_Katana_noBG.jpg"},{"name":"Yamaha XS650","rarity":"epic","id":"yamaha-xs650","subtitle":"Japanese Sport & Standards","details":"Yamaha's XS650 parallel twin was a rugged, torquey standard in the British mould, later beloved by custom builders and flat-track racers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Yamaha_XS650_%281977%29.jpg/1280px-Yamaha_XS650_%281977%29.jpg"},{"name":"Honda VFR750F","rarity":"epic","id":"honda-vfr750f","subtitle":"Japanese Sport & Standards","details":"The VFR750F's gear-driven-cam V4, aluminium frame and all-round polish made it the thinking rider's sports-tourer for over a decade.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/1991_VFR_750_in_red.jpg/1280px-1991_VFR_750_in_red.jpg"},{"name":"Kawasaki KZ1000","rarity":"epic","id":"kawasaki-kz1000","subtitle":"Japanese Sport & Standards","details":"The KZ1000 carried Kawasaki's air-cooled four into legend as a police mount, drag racer and screen star of the Mad Max era.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/1979_KZ1000LTD.jpg/1280px-1979_KZ1000LTD.jpg"},{"name":"Suzuki GSX-R1100","rarity":"epic","id":"suzuki-gsx-r1100","subtitle":"Japanese Sport & Standards","details":"The GSX-R1100 added oil-cooled muscle to Suzuki's racer-replica formula, a big-bore superbike prized for its engine's brutal midrange.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Suzuki_GSX-R1100_Eicma_2024.jpg/1280px-Suzuki_GSX-R1100_Eicma_2024.jpg"},{"name":"Yamaha FZR1000","rarity":"epic","id":"yamaha-fzr1000","subtitle":"Japanese Sport & Standards","details":"Yamaha's FZR1000 EXUP used an exhaust valve to fatten midrange from its five-valve four, topping superbike tests at the end of the 1980s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/Yamaha_FZR1000_Exup.jpg/1280px-Yamaha_FZR1000_Exup.jpg"},{"name":"BMW R80 G/S","rarity":"epic","id":"bmw-r-80-gs","subtitle":"Dirt, Adventure & Off-Road","details":"The R 80 G/S of 1980 created the adventure class with a 798cc boxer twin in a trail-ready chassis; the later GS models carried its formula onward.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/BMW_R80GS_1981_B.jpg/1280px-BMW_R80GS_1981_B.jpg"},{"name":"Kawasaki KLR650","rarity":"epic","id":"kawasaki-klr650","subtitle":"Dirt, Adventure & Off-Road","details":"Kawasaki's KLR650 is a famously unkillable 651cc single-cylinder dual-sport, prized for its big fuel tank, rugged design and low price.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Kawasaki_KLR_650_01.jpg/1280px-Kawasaki_KLR_650_01.jpg"},{"name":"Honda XRV750 Africa Twin","rarity":"epic","id":"honda-xrv750-africa-twin","subtitle":"Dirt, Adventure & Off-Road","details":"The original Africa Twin paired a 742cc V-twin with rally styling from Honda's Dakar winners, becoming a cult overland machine.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Honda_Africa_Twin_XRV750T.jpg/1280px-Honda_Africa_Twin_XRV750T.jpg"},{"name":"KTM 1290 Super Adventure","rarity":"epic","id":"ktm-1290-super-adventure","subtitle":"Dirt, Adventure & Off-Road","details":"KTM's 1,301cc LC8 V-twin flagship brought superbike-level power to adventure touring, with semi-active suspension and full rider electronics.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/KTM_1290_Super_Adventure.jpeg/1280px-KTM_1290_Super_Adventure.jpeg"},{"name":"Triumph Tiger 800","rarity":"epic","id":"triumph-tiger-800","subtitle":"Dirt, Adventure & Off-Road","details":"Triumph's middleweight adventure bike used an 800cc three-cylinder engine, giving the Tiger a smooth, characterful alternative to twin rivals.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Triumph_Tiger_800_MY_2012_side_view.jpg/1280px-Triumph_Tiger_800_MY_2012_side_view.jpg"},{"name":"Yamaha Ténéré 700","rarity":"epic","id":"yamaha-tenere-700","subtitle":"Dirt, Adventure & Off-Road","details":"The Ténéré 700 pairs Yamaha's CP2 689cc parallel twin with a light steel frame and long-travel suspension, a back-to-basics rally-bred adventurer.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Tenere_700.jpg/1280px-Tenere_700.jpg"},{"name":"Honda Monkey Z50","rarity":"epic","id":"honda-monkey-z50","subtitle":"Scooters, Minis & Oddballs","details":"Honda's Z50 Monkey shrank the motorcycle to pocket size with a 49cc engine, folding handlebars and tiny wheels built for fun at campgrounds and pits.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Honda_monkey_Z50.jpg/960px-Honda_monkey_Z50.jpg"},{"name":"Vespa Rally 200","rarity":"epic","id":"vespa-rally-200","subtitle":"Scooters, Minis & Oddballs","details":"The Rally 200 carried Vespa's largest two-stroke of its day plus electronic ignition, with the spare wheel tucked under its left side panel.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Vespa_Rally_200_Electronic_1974.JPG/960px-Vespa_Rally_200_Electronic_1974.JPG"},{"name":"Can-Am Spyder F3-S","rarity":"epic","id":"can-am-spyder-f3-s","subtitle":"Scooters, Minis & Oddballs","details":"BRP's Spyder F3-S flips the trike layout with two wheels in front and one behind, powered by a Rotax triple and built for open-air cruising.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/2024_Can-Am_Spyder_F3-S.jpg/960px-2024_Can-Am_Spyder_F3-S.jpg"},{"name":"Evel Knievel's Harley XR-750","rarity":"epic","id":"evel-knievel-xr750","subtitle":"Famous & Movie Bikes","details":"Evel Knievel jumped buses, fountains and canyons on Harley-Davidson XR-750s like this one, displayed mid-jump at the Harley-Davidson Museum.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Harley-Davidson_Museum_Evel_Knievel_Bike.JPG/1280px-Harley-Davidson_Museum_Evel_Knievel_Bike.JPG"},{"name":"Top Gun Kawasaki GPZ900R","rarity":"epic","id":"top-gun-gpz900r","subtitle":"Famous & Movie Bikes","details":"Maverick's Kawasaki GPZ900R Ninja raced an F-14 down the runway in Top Gun, and the same bike returned decades later in Top Gun: Maverick.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Kawasaki_GPz900R_Ninja_A2_used_in_Top_Gun%EF%BC%9AMaverick.jpg/1280px-Kawasaki_GPz900R_Ninja_A2_used_in_Top_Gun%EF%BC%9AMaverick.jpg"},{"name":"The Dark Knight Batpod","rarity":"epic","id":"dark-knight-batpod","subtitle":"Famous & Movie Bikes","details":"The Batpod bursts out of the wrecked Tumbler in The Dark Knight, its twin cannons and fat tyres turning Batman's escape into pure comic-book engineering.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ae/Batpod.jpg"},{"name":"The Matrix Reloaded Ducati 996","rarity":"epic","id":"matrix-reloaded-ducati-996","subtitle":"Famous & Movie Bikes","details":"Trinity steals this dark green Ducati 996 for the freeway chase in The Matrix Reloaded, weaving through traffic in one of cinema's great bike sequences.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Ducati_996_Matrix.jpg/1280px-Ducati_996_Matrix.jpg"},{"name":"Mad Max Goose Kawasaki KZ1000","rarity":"epic","id":"mad-max-goose-kz1000","subtitle":"Famous & Movie Bikes","details":"MFP officer Jim 'Goose' Rains rides this faired Kawasaki KZ1000 in Mad Max, the silver and blue Main Force Patrol bike built for speed in a dying world.","image":"https://images.bikeexif.com/2022/11/kawasaki-kz1000-mad-max.jpg"},{"name":"Tron: Legacy Light Cycle","rarity":"epic","id":"tron-legacy-light-cycle","subtitle":"Famous & Movie Bikes","details":"Sam Flynn rides a fifth-generation Light Cycle in Tron: Legacy, the glowing machine that turned the Grid's deadliest game into a neon ballet.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Comic-Con_2010_-_Disney_Tron_Legacy_booth_-_light_cycle_%284859615650%29.jpg/1280px-Comic-Con_2010_-_Disney_Tron_Legacy_booth_-_light_cycle_%284859615650%29.jpg"},{"name":"Hildebrand & Wolfmüller","rarity":"epic","id":"hildebrand-wolfmuller","subtitle":"Historic Pioneers","details":"Sold from 1894, this Munich machine is credited as the first series-production motorcycle, with a water-cooled twin driving the rear wheel.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Hildebrand_%26_Wolfmuller_UMMC_Museum.jpg/1280px-Hildebrand_%26_Wolfmuller_UMMC_Museum.jpg"},{"name":"FN Four","rarity":"epic","id":"fn-four","subtitle":"Historic Pioneers","details":"Belgium's FN built the world's first production inline-four motorcycle from 1905, with shaft drive and a 363cc engine designed by Paul Kelecom.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/1905_FN_Four_Cylinder_Petersen_Automotive_Museum.jpg/1280px-1905_FN_Four_Cylinder_Petersen_Automotive_Museum.jpg"},{"name":"Henderson Four","rarity":"epic","id":"henderson-four","subtitle":"Historic Pioneers","details":"William Henderson's 1912 Four offered a 934cc inline-four and chain drive; Hendersons became famed for smooth, luxurious long-distance touring.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/1913_Henderson_Four_motorcycle_01.JPG/1280px-1913_Henderson_Four_motorcycle_01.JPG"},{"name":"Pierce Four","rarity":"epic","id":"pierce-four","subtitle":"Historic Pioneers","details":"Inspired by the FN, Percy Pierce's 1909 Four hid its fuel in fat frame tubes and ran a T-head inline-four built in Buffalo, New York.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/1910PierceFour-Barber.jpg/1280px-1910PierceFour-Barber.jpg"},{"name":"Indian Four","rarity":"epic","id":"indian-four","subtitle":"Historic Pioneers","details":"Indian's luxury flagship, descended from the Ace Four, ran a 1,265cc inline-four and was marketed to police fleets and well-heeled tourists.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Indian_Four_1265_ccm_%281931%29_in_NTM_Prague.jpg/1280px-Indian_Four_1265_ccm_%281931%29_in_NTM_Prague.jpg"},{"name":"Indian 101 Scout","rarity":"epic","id":"indian-101-scout","subtitle":"Historic Pioneers","details":"The 101 Scout of 1928 is often called the best Indian ever built, its 750cc V-twin praised for balance, reliability and sweet handling.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Indian_Scout_101_1928_%2814744787028%29.jpg/1280px-Indian_Scout_101_1928_%2814744787028%29.jpg"},{"name":"Harley-Davidson Hydra-Glide","rarity":"rare","id":"harley-davidson-hydra-glide","subtitle":"American Cruisers","details":"The 1949 Hydra-Glide introduced hydraulic front forks on Harley's big twins, its name carried on the front fender badge through the Panhead years.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Harley-Davidson_Museum_April_2024_27_%281949_FL_Hydra-Glide--OHV_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_April_2024_27_%281949_FL_Hydra-Glide--OHV_V-Twin%29.jpg"},{"name":"Harley-Davidson Heritage Softail Classic","rarity":"rare","id":"harley-davidson-heritage-softail-classic","subtitle":"American Cruisers","details":"The Heritage Softail Classic wraps a studded leather saddle and bags around retro 1940s styling, hiding its rear suspension for a hardtail look.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/Paris_-_Salon_de_la_moto_2011_-_Harley-Davidson_-_FLSTC_Heritage_Softail_Classic_-_001.jpg/1280px-Paris_-_Salon_de_la_moto_2011_-_Harley-Davidson_-_FLSTC_Heritage_Softail_Classic_-_001.jpg"},{"name":"Harley-Davidson Dyna Wide Glide","rarity":"rare","id":"harley-davidson-dyna-wide-glide","subtitle":"American Cruisers","details":"The Dyna Wide Glide runs a raked wide front end, sissy bar and a bobbed rear fender, chopper styling on Harley's rubber-mounted Dyna frame.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Dyna_Wide_Glide.jpg/1280px-Dyna_Wide_Glide.jpg"},{"name":"Harley-Davidson Dyna Super Glide","rarity":"rare","id":"harley-davidson-dyna-super-glide","subtitle":"American Cruisers","details":"The Dyna Super Glide carried the FX formula forward on the rubber-mounted Dyna chassis, a midweight big twin prized for its handling balance.","image":"https://upload.wikimedia.org/wikipedia/commons/9/90/Harley_Davidson_1999_Dyna_Super_Glide_FXD_%2813895755549%29.jpg"},{"name":"Harley-Davidson Breakout","rarity":"rare","id":"harley-davidson-breakout","subtitle":"American Cruisers","details":"The Breakout is a long, low Softail muscle cruiser with a fat 240mm rear tire, chopped fenders and a stance modeled on drag-strip pro-stock bikes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/Harley-Davidson_Softail_Breakout_FXSB103_%282015-08-25_Sp%29.jpg/1280px-Harley-Davidson_Softail_Breakout_FXSB103_%282015-08-25_Sp%29.jpg"},{"name":"Harley-Davidson Fat Bob","rarity":"rare","id":"harley-davidson-fat-bob","subtitle":"American Cruisers","details":"The Fat Bob pairs twin front disc brakes and a chunky front tire with drag bars, a Dyna-born brawler later rebuilt on the Softail chassis.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Harley_Davidson_Fat_Bob_114.jpg/1280px-Harley_Davidson_Fat_Bob_114.jpg"},{"name":"Harley-Davidson Sportster Forty-Eight","rarity":"rare","id":"harley-davidson-sportster-forty-eight","subtitle":"American Cruisers","details":"The Sportster Forty-Eight takes its name from its 1948-style small peanut tank, riding low on fat tires with under-bar mirrors and blacked-out trim.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Sportster_Forty-Eight.jpeg/1280px-Sportster_Forty-Eight.jpeg"},{"name":"Harley-Davidson Sportster Nightster","rarity":"rare","id":"harley-davidson-sportster-nightster","subtitle":"American Cruisers","details":"The 2007 Nightster joined Harley's Dark Custom push: a blacked-out 1200 Sportster with bobbed fenders, a side-mount plate and a low solo saddle.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/HarleyDavidson_XL_1200N_Sportster_1200_Nightster_2008.jpg/1280px-HarleyDavidson_XL_1200N_Sportster_1200_Nightster_2008.jpg"},{"name":"Indian Chief Dark Horse","rarity":"rare","id":"indian-chief-dark-horse","subtitle":"American Cruisers","details":"The Chief Dark Horse blacked out Indian's big cruiser, from its Thunder Stroke engine to its valanced fenders, keeping only flashes of chrome.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Indian_Chief_Dark_Horse_%282%29.jpg/1280px-Indian_Chief_Dark_Horse_%282%29.jpg"},{"name":"Indian Scout Bobber","rarity":"rare","id":"indian-scout-bobber","subtitle":"American Cruisers","details":"The Scout Bobber strips Indian's middleweight to bar-end mirrors and chopped fenders, with blacked-out finishes and a slammed solo seat.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Indian_Scout_%2820938880732%29.jpg/1280px-Indian_Scout_%2820938880732%29.jpg"},{"name":"Harley-Davidson CVO Road Glide","rarity":"rare","id":"harley-davidson-cvo-road-glide","subtitle":"American Cruisers","details":"The CVO Road Glide is Harley's limited-production flagship tourer, pairing the shark-nose fairing with Milwaukee-Eight 117 power and premium paint.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/2019_Harley-Davidson_CVO_Road_Glide_in_Red_Pepper_%26_Magnetic_Grey_With_Black_Hole.jpg/1280px-2019_Harley-Davidson_CVO_Road_Glide_in_Red_Pepper_%26_Magnetic_Grey_With_Black_Hole.jpg"},{"name":"Harley-Davidson Duo-Glide","rarity":"rare","id":"harley-davidson-duo-glide","subtitle":"American Cruisers","details":"The 1958 Duo-Glide added rear swingarm suspension to Harley's big twin, joining the front Hydra-Glide fork to give riders a fully suspended flagship.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Harley-Davidson_Museum_April_2024_30_%281958_FL_Duo-Glide--OHV_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_April_2024_30_%281958_FL_Duo-Glide--OHV_V-Twin%29.jpg"},{"name":"Triumph Bonneville T140","rarity":"rare","id":"triumph-bonneville-t140","subtitle":"British & European Classics","details":"The 744cc successor to the T120 added a five-speed gearbox, disc brakes and left-foot gearchange as the Bonneville entered its final Meriden years.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Triumph_T140_Bonneville_%281975%29_-_15752701316.jpg/960px-Triumph_T140_Bonneville_%281975%29_-_15752701316.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BSA A65 Lightning","rarity":"rare","id":"bsa-a65-lightning","subtitle":"British & European Classics","details":"BSA's unit-construction 654cc twin answered American demand for pace with twin carburettors, 12-volt electrics and bright chrome bodywork.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/BSA_A65_Lightning_%281968%29_-_15916723752.jpg/960px-BSA_A65_Lightning_%281968%29_-_15916723752.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Norton Atlas","rarity":"rare","id":"norton-atlas","subtitle":"British & European Classics","details":"The Atlas stretched Norton's featherbed-framed twin to 745cc, using the slimline frame to keep big-twin torque on a sporting chassis.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/1966_Norton_Atlas_750.JPG/960px-1966_Norton_Atlas_750.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BMW R75/5","rarity":"rare","id":"bmw-r75-5","subtitle":"British & European Classics","details":"The /5 series rebooted BMW in 1969 with electric starting, telescopic forks and the 745cc boxer twin in short-wheelbase sporting trim.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/BMW_R_75-5_%282014-09-13_7126b%29.JPG/960px-BMW_R_75-5_%282014-09-13_7126b%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ducati 900 Super Sport","rarity":"rare","id":"ducati-900-super-sport","subtitle":"British & European Classics","details":"The original 900 Super Sport carried Ducati's bevel-drive 864cc desmo V-twin in a steel cradle frame beneath a sleek half fairing.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Ducati_900ss_-_8051764696.jpg/960px-Ducati_900ss_-_8051764696.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"MV Agusta F4","rarity":"rare","id":"mv-agusta-f4","subtitle":"British & European Classics","details":"The F4 revived MV Agusta with Tamburini styling, a radial-valve four-cylinder engine and four organ-pipe exhausts tucked under the tail.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/MV_Agusta_F4_%281%29.jpg/960px-MV_Agusta_F4_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Moto Guzzi California","rarity":"rare","id":"moto-guzzi-california","subtitle":"British & European Classics","details":"Born from LAPD patrol bikes, the California cruised on floorboards and a big screen, its transverse V-twin serving police fleets across America.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Moto_Guzzi_850_GT_California_%281%29.jpg/960px-Moto_Guzzi_850_GT_California_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Royal Enfield Interceptor 650","rarity":"rare","id":"royal-enfield-interceptor-650","subtitle":"British & European Classics","details":"Enfield's 648cc air-oil-cooled parallel twin revived a famous name with easy torque, twin clocks and classic British roadster proportions.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Royal_Enfield_INT_650_motorcycle.jpg/960px-Royal_Enfield_INT_650_motorcycle.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Matchless G80","rarity":"rare","id":"matchless-g80","subtitle":"British & European Classics","details":"AMC's 498cc single offered dependable, unhurried power in a swinging-arm frame, a gentleman's roadster from Plumstead's London works.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/1961_Matchless_G80CS_right_side.jpg/960px-1961_Matchless_G80CS_right_side.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Sunbeam S7","rarity":"rare","id":"sunbeam-s7","subtitle":"British & European Classics","details":"Sunbeam's luxury tourer used a car-style inline twin mounted lengthwise, shaft drive and balloon tyres for unusually serene progress.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Sunbeam_S7_%281954%29.jpg/960px-Sunbeam_S7_%281954%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ducati Monster 900","rarity":"rare","id":"ducati-monster-900","subtitle":"British & European Classics","details":"Miguel Galuzzi's Monster stripped Ducati's 904cc V-twin to the essentials — engine, trellis frame, tank and seat — inventing the modern naked bike.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Ducati_Monster_900_del_1993.jpg/960px-Ducati_Monster_900_del_1993.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BMW K100","rarity":"rare","id":"bmw-k100","subtitle":"British & European Classics","details":"BMW's 'flying brick' laid its 987cc fuel-injected four flat along the frame, driving the rear wheel by shaft beneath angular bodywork.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/BMW_K100_in_the_BMW_Museum_2025-05.jpg/960px-BMW_K100_in_the_BMW_Museum_2025-05.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Honda CB400 Four","rarity":"rare","id":"honda-cb400-four","subtitle":"Japanese Sport & Standards","details":"The CB400 Four's swooping four-into-one exhaust and jewel-like 408cc engine made this cafe-styled middleweight a connoisseur's favourite.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Honda_CB400_Four_cropped.JPG/1280px-Honda_CB400_Four_cropped.JPG"},{"name":"Kawasaki H1 Mach III","rarity":"rare","id":"kawasaki-h1-mach-iii","subtitle":"Japanese Sport & Standards","details":"The 1969 Mach III put a 60hp three-cylinder two-stroke in a light frame, delivering explosive pace that defined the original Kawasaki triple.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/1969_Kawasaki_500_H1_MachIII.jpg/1280px-1969_Kawasaki_500_H1_MachIII.jpg"},{"name":"Yamaha RZ350","rarity":"rare","id":"yamaha-rz350","subtitle":"Japanese Sport & Standards","details":"The RZ350 was the last great street two-stroke twin in many markets, its liquid-cooled YPVS engine delivering sharp, smoky sportsbike thrills.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f8/YAMAHA_RZ350_005.jpg"},{"name":"Suzuki TL1000S","rarity":"rare","id":"suzuki-tl1000s","subtitle":"Japanese Sport & Standards","details":"Suzuki's TL1000S wrapped a potent 996cc V-twin in an oval-section frame, a characterful superbike famed for its engine's instant drive.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Suzuki_TL1000S%2C_red.jpg/1280px-Suzuki_TL1000S%2C_red.jpg"},{"name":"Honda RC51","rarity":"rare","id":"honda-rc51","subtitle":"Japanese Sport & Standards","details":"Honda's VTR1000 SP, sold as the RC51 in America, used a 999cc V-twin to beat Ducati at its own game, winning World Superbike titles.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/2001_Honda_RC51_SP1.jpg/1280px-2001_Honda_RC51_SP1.jpg"},{"name":"Kawasaki ZX-7R","rarity":"rare","id":"kawasaki-zx-7r","subtitle":"Japanese Sport & Standards","details":"The Ninja ZX-7R's endurance-racer looks backed real success, carrying Kawasaki's 750 challenge through a decade of superbike racing.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Kawasaki_Ninja_ZX-7R%2C_1997.jpg/1280px-Kawasaki_Ninja_ZX-7R%2C_1997.jpg"},{"name":"Yamaha SR400","rarity":"rare","id":"yamaha-sr400","subtitle":"Japanese Sport & Standards","details":"The SR400 kept faith with the classic single - air-cooled, kick-start only and slim, a back-to-basics standard sold across four decades.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/Yamaha_SR400_Motorcycle_2014.JPG/1280px-Yamaha_SR400_Motorcycle_2014.JPG"},{"name":"Suzuki SV650","rarity":"rare","id":"suzuki-sv650","subtitle":"Japanese Sport & Standards","details":"The original SV650's aluminium trellis frame and 645cc V-twin delivered big-bike character at a middleweight price, a modern cult classic.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/2002_Suzuki_SV_650_%28III%29.JPG/1280px-2002_Suzuki_SV_650_%28III%29.JPG"},{"name":"Honda CX500","rarity":"rare","id":"honda-cx500","subtitle":"Japanese Sport & Standards","details":"The CX500's transverse V-twin, shaft drive and liquid cooling were pure Honda lateral thinking, earning a courier-proof reputation for toughness.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Honda_CX500%2C_blue.jpg/1280px-Honda_CX500%2C_blue.jpg"},{"name":"Kawasaki GPZ750 Turbo","rarity":"rare","id":"kawasaki-gpz750-turbo","subtitle":"Japanese Sport & Standards","details":"Kawasaki's GPZ750 Turbo used a factory turbocharger to chase litre-bike pace, the most usable of the short-lived 1980s turbo bikes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/1985_Kawasaki_ZX750-E2_Turbo%2C_front_left.jpg/1280px-1985_Kawasaki_ZX750-E2_Turbo%2C_front_left.jpg"},{"name":"Yamaha XJ650","rarity":"rare","id":"yamaha-xj650","subtitle":"Japanese Sport & Standards","details":"The XJ650 paired an air-cooled 653cc four with shaft drive, a smooth and durable standard that anchored Yamaha's middleweight line.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Yamaha_XJ_650_1983.JPG/1280px-Yamaha_XJ_650_1983.JPG"},{"name":"Honda VFR800","rarity":"rare","id":"honda-vfr800","subtitle":"Japanese Sport & Standards","details":"The VFR800 carried Honda's V4 sports-touring line forward with VTEC valve timing and linked brakes in a polished package.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Honda_VFR800_red.jpg/1280px-Honda_VFR800_red.jpg"},{"name":"Honda VF750F","rarity":"rare","id":"honda-vf750f","subtitle":"Japanese Sport & Standards","details":"The VF750F Interceptor brought Honda's V4 and a 16-inch front wheel to the sports class, the first of the Interceptor line in 1983.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d9/1983_Honda_Interceptor_VF750F.jpg"},{"name":"Suzuki DR650","rarity":"rare","id":"suzuki-dr650","subtitle":"Dirt, Adventure & Off-Road","details":"Suzuki's DR650 is a 644cc air- and oil-cooled single that has changed little since the 1990s, loved for its simplicity and go-anywhere toughness.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9a/Suzuki_DR650RSE.jpg"},{"name":"Suzuki DL650 V-Strom","rarity":"rare","id":"suzuki-dl650-v-strom","subtitle":"Dirt, Adventure & Off-Road","details":"The V-Strom 650 brought Suzuki's 645cc V-twin to adventure touring, earning a loyal following as a comfortable, economical all-rounder.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/2015_Suzuki_V-Strom_650XT_ABS.JPG/1280px-2015_Suzuki_V-Strom_650XT_ABS.JPG"},{"name":"Husqvarna 701 Enduro","rarity":"rare","id":"husqvarna-701-enduro","subtitle":"Dirt, Adventure & Off-Road","details":"Husqvarna's 701 Enduro is a featherweight big-single dual-sport: a 692cc thumper in a trellis frame, close kin to KTM's 690 Enduro R.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f9/Husqvarna_701_Enduro.jpg"},{"name":"Ducati DesertX","rarity":"rare","id":"ducati-desertx","subtitle":"Dirt, Adventure & Off-Road","details":"Ducati's DesertX revived the spirit of the Cagiva Elefant Dakar bikes with a 937cc Testastretta twin, 21-inch front wheel and rally styling.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Ducati_DesertX_in_Barcelona.jpg/1280px-Ducati_DesertX_in_Barcelona.jpg"},{"name":"Moto Guzzi V85 TT","rarity":"rare","id":"moto-guzzi-v85-tt","subtitle":"Dirt, Adventure & Off-Road","details":"Moto Guzzi's V85 TT is a retro-styled adventure tourer built around an air-cooled 853cc transverse V-twin with shaft drive, a Guzzi signature.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Moto_Guzzi_V85_TT%2C_2020_%282%29.jpg/1280px-Moto_Guzzi_V85_TT%2C_2020_%282%29.jpg"},{"name":"Royal Enfield Himalayan","rarity":"rare","id":"royal-enfield-himalayan","subtitle":"Dirt, Adventure & Off-Road","details":"Royal Enfield's Himalayan is a simple 411cc single-cylinder adventure bike built for rough roads, named for the mountains where it was tested.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Royal_Enfield_Himalayan_%282%29.jpg/1280px-Royal_Enfield_Himalayan_%282%29.jpg"},{"name":"BMW F 850 GS","rarity":"rare","id":"bmw-f-850-gs","subtitle":"Dirt, Adventure & Off-Road","details":"BMW's middleweight GS uses an 853cc parallel twin in a steel bridge frame, slotting between the single-cylinder G 310 GS and the big boxers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/BMW_F850GS_left_side.jpg/1280px-BMW_F850GS_left_side.jpg"},{"name":"Yamaha XT660Z Ténéré","rarity":"rare","id":"yamaha-xt660z-tenere","subtitle":"Dirt, Adventure & Off-Road","details":"Yamaha's XT660Z Ténéré was a 660cc single-cylinder adventure bike with a tall rally fairing, twin headlights and a 23-litre tank for long stages.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/XT660ZTenere.JPG/1280px-XT660ZTenere.JPG"},{"name":"Honda XR650L","rarity":"rare","id":"honda-xr650l","subtitle":"Dirt, Adventure & Off-Road","details":"Honda's XR650L is an air-cooled 644cc dual-sport that has carried the XR badge for decades, a simple electric-start thumper on XR600R foundations.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/1993_Honda_XR650L_01.jpg/1280px-1993_Honda_XR650L_01.jpg"},{"name":"Aprilia Tuareg 660","rarity":"rare","id":"aprilia-tuareg-660","subtitle":"Dirt, Adventure & Off-Road","details":"Aprilia revived the Tuareg name for a 659cc parallel-twin adventurer, tuned for dirt with long suspension travel and a light, rally-focused chassis.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Aprilia_Tuareg_660_%28bearb_Sp%29.jpg/1280px-Aprilia_Tuareg_660_%28bearb_Sp%29.jpg"},{"name":"Honda Motocompo","rarity":"rare","id":"honda-motocompo","subtitle":"Scooters, Minis & Oddballs","details":"Honda's Motocompo folded flat — its bars, seat and pegs tucking into the boxy body — so it could ride in the trunk of the Honda City hatchback.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b0/Motoco_01.jpg"},{"name":"Honda CT70","rarity":"rare","id":"honda-ct70","subtitle":"Scooters, Minis & Oddballs","details":"Honda's CT70 Mini Trail packed a 72cc four-stroke into a pressed-steel frame with fat tires and folding bars, introducing generations of riders.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/1972_Honda_CT70_Mini_Trail.jpg/960px-1972_Honda_CT70_Mini_Trail.jpg"},{"name":"Piaggio MP3","rarity":"rare","id":"piaggio-mp3","subtitle":"Scooters, Minis & Oddballs","details":"Piaggio's MP3 leans through corners on two front wheels, using a parallelogram linkage that can also lock the scooter upright when it stops.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Piaggio_MP3_250ie.jpg/960px-Piaggio_MP3_250ie.jpg"},{"name":"Suzuki Burgman 650","rarity":"rare","id":"suzuki-burgman-650","subtitle":"Scooters, Minis & Oddballs","details":"Suzuki's Burgman 650 maxi-scooter pairs a 638cc twin with an electronically controlled CVT, giving step-through comfort with touring-bike power.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/BURGMAN650_K6.JPG/960px-BURGMAN650_K6.JPG"},{"name":"Ural Gear Up","rarity":"rare","id":"ural-gear-up","subtitle":"Scooters, Minis & Oddballs","details":"Ural's Gear Up sidecar outfit can drive both the rear wheel and the chair wheel, adding traction for mud, snow and rough back roads.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Ural_Gear-Up_motorcycle_%2814384585886%29.jpg/960px-Ural_Gear-Up_motorcycle_%2814384585886%29.jpg"},{"name":"Vespa GTS 300","rarity":"rare","id":"vespa-gts-300","subtitle":"Scooters, Minis & Oddballs","details":"The GTS 300 is Vespa's modern flagship, matching the classic steel monocoque body to a liquid-cooled 300cc-class single with highway pace.","image":"https://upload.wikimedia.org/wikipedia/commons/6/62/Vespa_GTS_300.jpg"},{"name":"Easy Rider Billy Bike","rarity":"rare","id":"easy-rider-billy-bike","subtitle":"Famous & Movie Bikes","details":"Dennis Hopper's Billy rides this flame-tanked Harley chopper beside Captain America in Easy Rider, carrying half of the most famous duo in biker cinema.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/1969_Billy_Bike_chopper_replica_Goodwood%2C_2009_%2801%29.jpg/1280px-1969_Billy_Bike_chopper_replica_Goodwood%2C_2009_%2801%29.jpg"},{"name":"1966 Batman Batcycle","rarity":"rare","id":"batman-1966-batcycle","subtitle":"Famous & Movie Bikes","details":"Built from a Yamaha YDS-3, the 1966 Batcycle carried Batman and Robin into action on TV, complete with Robin's detachable sidecar go-kart.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/1966_Batman_Batcycle_Petersen_Automotive_Museum.jpg/1280px-1966_Batman_Batcycle_Petersen_Automotive_Museum.jpg"},{"name":"Tomorrow Never Dies BMW R1200C","rarity":"rare","id":"tomorrow-never-dies-bmw-r1200c","subtitle":"Famous & Movie Bikes","details":"Bond and Wai Lin escape handcuffed together on this BMW R1200C in Tomorrow Never Dies, leaping rooftops and a helicopter through the streets of Saigon.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/BMW_R1200_%28Tomorrow_Never_Dies%29_National_Motor_Museum%2C_Beaulieu.jpg/1280px-BMW_R1200_%28Tomorrow_Never_Dies%29_National_Motor_Museum%2C_Beaulieu.jpg"},{"name":"Hagrid's Motorcycle and Sidecar","rarity":"rare","id":"hagrids-motorcycle-sidecar","subtitle":"Famous & Movie Bikes","details":"Hagrid's flying motorcycle and sidecar delivers baby Harry to Privet Drive in Harry Potter, a Triumph outfit borrowed from Sirius Black.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Hagrid%27s_Motorcycle_%2829320645736%29.jpg/1280px-Hagrid%27s_Motorcycle_%2829320645736%29.jpg"},{"name":"Long Way Round BMW R1150GS","rarity":"rare","id":"long-way-round-bmw-r1150gs","subtitle":"Famous & Movie Bikes","details":"Ewan McGregor and Charley Boorman rode BMW R1150GS Adventures 20,000 miles around the world for the TV series Long Way Round.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/BMW_Long_Way_Round.jpg/1280px-BMW_Long_Way_Round.jpg"},{"name":"Akira Kaneda's Bike","rarity":"rare","id":"akira-kaneda-bike","subtitle":"Famous & Movie Bikes","details":"Kaneda's red superbike is the icon of Akira, the 1988 anime landmark; this full-size real-world build recreates its sliding-seat, stickered bodywork.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Kaneda%27s_motorcycle.jpg/1280px-Kaneda%27s_motorcycle.jpg"},{"name":"Jurassic World Triumph Scrambler","rarity":"rare","id":"jurassic-world-triumph-scrambler","subtitle":"Famous & Movie Bikes","details":"Owen Grady rides this Triumph Scrambler alongside his raptor pack in Jurassic World, outpacing the Indominus rex through the jungle of Isla Nublar.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/2014_Triumph_Scrambler_Jurassic_World_Custom.jpg/1280px-2014_Triumph_Scrambler_Jurassic_World_Custom.jpg"},{"name":"On Any Sunday Husqvarna 250 Cross","rarity":"rare","id":"on-any-sunday-husqvarna","subtitle":"Famous & Movie Bikes","details":"Steve McQueen and his Husqvarna star in On Any Sunday, Bruce Brown's 1971 documentary that introduced a generation to the joy of motorcycle racing.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/1970_Husqvarna_250_Cross_On_Any_Sunday_Petersen_Automotive_Museum.jpg/1280px-1970_Husqvarna_250_Cross_On_Any_Sunday_Petersen_Automotive_Museum.jpg"},{"name":"Daryl Dixon's Walking Dead Honda","rarity":"rare","id":"daryl-dixon-walking-dead-honda","subtitle":"Famous & Movie Bikes","details":"Classified Moto rebuilt a 1992 Honda CB750 Nighthawk into Daryl Dixon's crossbow-carrying survival bike for The Walking Dead.","image":"https://images.bikeexif.com/2015/03/daryl-dixon-motorcycle-1.jpg"},{"name":"Excelsior Super X","rarity":"rare","id":"excelsior-super-x","subtitle":"Historic Pioneers","details":"Chicago's Super X was America's first 750cc production motorcycle, a V-twin built to challenge Indian's Scout on road and board track alike.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/1929_Excelsior_SuperX_Petersen_Automotive_Museum.jpg/1280px-1929_Excelsior_SuperX_Petersen_Automotive_Museum.jpg"},{"name":"Harley-Davidson JD","rarity":"rare","id":"harley-davidson-jd","subtitle":"Historic Pioneers","details":"The JD paired a 1,000cc intake-over-exhaust V-twin with a three-speed gearbox, Harley-Davidson's flagship tourer of the late 1920s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/1929_Harley_Davidson_JD_1000_24hp_1000cc_pic1.JPG/1280px-1929_Harley_Davidson_JD_1000_24hp_1000cc_pic1.JPG"},{"name":"Indian Scout","rarity":"rare","id":"indian-scout","subtitle":"Historic Pioneers","details":"Debuting in 1920 with a 600cc V-twin and gear primary drive, Charles Franklin's Scout was light, low and famously tough for its size.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/1922_Indian_Scout_600cc_%2814788988671%29.jpg/1280px-1922_Indian_Scout_600cc_%2814788988671%29.jpg"},{"name":"Indian Powerplus","rarity":"rare","id":"indian-powerplus","subtitle":"Historic Pioneers","details":"The Powerplus replaced Indian's earlier valve layout with a side-valve 1,000cc V-twin from 1916, gaining a reputation for rugged power.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Indian_powerplus_1915.jpg/1280px-Indian_powerplus_1915.jpg"},{"name":"Norton CS1","rarity":"rare","id":"norton-cs1","subtitle":"Historic Pioneers","details":"Norton's first overhead-cam single, the CS1 of 1927 took its name from its camshaft drive and won the Senior TT in its debut year.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6c/1928_Norton_CS1_500cc-motorcycle_left_hand_side.jpg"},{"name":"Ariel Square Four","rarity":"rare","id":"ariel-square-four","subtitle":"Historic Pioneers","details":"Edward Turner's Square Four packed four cylinders into a compact square block from 1931, a silk-smooth tourer built by Ariel in Birmingham.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/1935_Ariel_Square_Four_02.JPG/1280px-1935_Ariel_Square_Four_02.JPG"},{"name":"Sunbeam Model 90","rarity":"rare","id":"sunbeam-model-90","subtitle":"Historic Pioneers","details":"Sunbeam's overhead-valve Model 90 was Wolverhampton's 500cc TT racer, a black-and-gold single campaigned at the Isle of Man from 1928.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d7/Sunbeam_1928_M90_racer_1.jpg"},{"name":"AJS Model K8","rarity":"rare","id":"ajs-model-k8","subtitle":"Historic Pioneers","details":"The K8 was A. J. Stevens' 500cc overhead-valve single for 1928, a sporting Wolverhampton machine from a great British racing family.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5b/AJS_Model_K8_500_cc_ohv_1928.jpg"},{"name":"Coventry-Eagle Flying-8","rarity":"rare","id":"coventry-eagle-flying-8","subtitle":"Historic Pioneers","details":"The Flying-8 topped Coventry-Eagle's range with a 980cc side-valve V-twin, a quiet, expensive luxury tourer built in small numbers.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7f/1925_Coventry-Eagle_Flying-8_980cc-motorcycle_right_front_side.jpg"},{"name":"Thor Model O","rarity":"rare","id":"thor-model-o","subtitle":"Historic Pioneers","details":"Aurora's Thor Model O ran a 1,000cc V-twin; Thor engines also powered the earliest Indians before Indian built its own motors.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/Hochgurgl-Top_Mountain_Motorcycle_Museum-Thor_Model_O-1916-1000ccm-02ESD.jpg/1280px-Hochgurgl-Top_Mountain_Motorcycle_Museum-Thor_Model_O-1916-1000ccm-02ESD.jpg"},{"name":"Harley-Davidson Softail Deluxe","rarity":"uncommon","id":"harley-davidson-softail-deluxe","subtitle":"American Cruisers","details":"The Softail Deluxe leans into nostalgia with whitewall tires, wide beach bars, full fenders and a low solo saddle over hidden rear suspension.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Harley_Davidson_FLSTN_Softail_Deluxe_1700_2013_%2814313407291%29.jpg/1280px-Harley_Davidson_FLSTN_Softail_Deluxe_1700_2013_%2814313407291%29.jpg"},{"name":"Harley-Davidson Wide Glide","rarity":"uncommon","id":"harley-davidson-wide-glide","subtitle":"American Cruisers","details":"The original 1980 Wide Glide FXWG brought factory chopper style with a flamed tank, sissy bar and 21-inch front wheel on a Shovelhead-era frame.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/Harley-Davidson_Museum_April_2024_43_%281980_FXWG_Wide_Glide--OHV_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_April_2024_43_%281980_FXWG_Wide_Glide--OHV_V-Twin%29.jpg"},{"name":"Harley-Davidson Sportster 883","rarity":"uncommon","id":"harley-davidson-sportster-883","subtitle":"American Cruisers","details":"The 883 Sportster was Harley's entry-level big-twin alternative for decades: an Evolution V-twin in a nimble frame, simple and endlessly customizable.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Harley-Davidson_Sportster_XL883_2007.JPG/1280px-Harley-Davidson_Sportster_XL883_2007.JPG"},{"name":"Harley-Davidson Sportster 1200 Custom","rarity":"uncommon","id":"harley-davidson-sportster-1200-custom","subtitle":"American Cruisers","details":"The Sportster 1200 Custom added cruiser polish to the 1200 Sportster, with a fat front tire, pullback bars and a larger teardrop fuel tank.","image":"https://upload.wikimedia.org/wikipedia/commons/1/17/2003_HD_XL1200C_Anniversary_Edition.jpg"},{"name":"Harley-Davidson Iron 883","rarity":"uncommon","id":"harley-davidson-iron-883","subtitle":"American Cruisers","details":"The Iron 883 was the entry Dark Custom Sportster: blacked-out engine and wheels, drag bars and a chopped rear fender on the 883 Evolution twin.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Paris_-_Salon_de_la_moto_2011_-_Harley-Davidson_-_XL_883N_Iron_883_-_001.jpg/1280px-Paris_-_Salon_de_la_moto_2011_-_Harley-Davidson_-_XL_883N_Iron_883_-_001.jpg"},{"name":"Indian Chief Vintage","rarity":"uncommon","id":"indian-chief-vintage","subtitle":"American Cruisers","details":"The Chief Vintage dressed Indian's big Thunder Stroke cruiser in tan leather saddlebags and fringe, a rolling tribute to the Chiefs of the 1940s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Indian_Chief_Vintage%2C_2014.jpg/1280px-Indian_Chief_Vintage%2C_2014.jpg"},{"name":"Victory Judge","rarity":"uncommon","id":"victory-judge","subtitle":"American Cruisers","details":"The Victory Judge mixed muscle-bike cues, mid-mount controls, drag bars and a fat rear tire, into a cruiser aimed at riding rather than posing.","image":"https://upload.wikimedia.org/wikipedia/commons/0/00/2012_Victory_Judge_motorcycle.jpg"},{"name":"Harley-Davidson Softail Slim","rarity":"uncommon","id":"harley-davidson-softail-slim","subtitle":"American Cruisers","details":"The Softail Slim channels postwar bobbers with a narrow rear end, Hollywood bars, half-moon floorboards and a cut-down front fender.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/2013_Harley_Davidson_Softtail_Slim_%288344193123%29.jpg/1280px-2013_Harley_Davidson_Softtail_Slim_%288344193123%29.jpg"},{"name":"Harley-Davidson Deuce","rarity":"uncommon","id":"harley-davidson-deuce","subtitle":"American Cruisers","details":"The Softail Deuce stood out with a stretched, sculpted fuel tank and a long chrome front end, Harley's sleek factory custom of the Twin Cam era.","image":"https://upload.wikimedia.org/wikipedia/commons/5/52/Harley-Davidson_Softail_Deuce_%282000%29.jpg"},{"name":"Harley-Davidson Heritage Springer","rarity":"uncommon","id":"harley-davidson-heritage-springer","subtitle":"American Cruisers","details":"The Heritage Springer paired a faithfully recreated 1948-style springer fork with modern Softail comfort, fringed leather and Evolution power.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/Harley-Davidson_Museum_May_2024_21_%281997_FLSTS_Heritage_Springer--OHV_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_May_2024_21_%281997_FLSTS_Heritage_Springer--OHV_V-Twin%29.jpg"},{"name":"Harley-Davidson Sport Glide","rarity":"uncommon","id":"harley-davidson-sport-glide","subtitle":"American Cruisers","details":"The Sport Glide is a convertible Softail cruiser whose detachable hard panniers and small fork fairing click off in seconds for stripped-down cruising.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Harley_Sport_Glide_2022.jpg/1280px-Harley_Sport_Glide_2022.jpg"},{"name":"Indian Chief Classic","rarity":"uncommon","id":"indian-chief-classic","subtitle":"American Cruisers","details":"The Chief Classic relaunched Indian's big cruiser in 2014 with valanced fenders, a leather saddle and the Thunder Stroke 111 V-twin.","image":"https://upload.wikimedia.org/wikipedia/commons/2/23/Indian_Chief_%2817155129087%29.jpg"},{"name":"Victory Vegas 8-Ball","rarity":"uncommon","id":"victory-vegas-8-ball","subtitle":"American Cruisers","details":"The Vegas 8-Ball was Victory's blacked-out budget custom: black paint, black wheels and a blacked-out Freedom V-twin on the sleek Vegas platform.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Paris_-_Salon_de_la_moto_2011_-_Victory_-_Vegas_8-Ball_-_001.jpg/1280px-Paris_-_Salon_de_la_moto_2011_-_Victory_-_Vegas_8-Ball_-_001.jpg"},{"name":"Victory Hammer","rarity":"uncommon","id":"victory-hammer","subtitle":"American Cruisers","details":"The Victory Hammer was a muscle cruiser built around a massive 250mm rear tire, inverted forks and the torquey Freedom 106 V-twin.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Paris_-_Salon_de_la_moto_2011_-_Victory_-_Hammer_S_-_001.jpg/1280px-Paris_-_Salon_de_la_moto_2011_-_Victory_-_Hammer_S_-_001.jpg"},{"name":"Harley-Davidson Softail Custom","rarity":"uncommon","id":"harley-davidson-softail-custom","subtitle":"American Cruisers","details":"The Softail Custom FXSTC dressed the standard Softail in extra chrome, a bobtail rear fender, pullback bars and a plush two-up seat for cruising comfort.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e5/Fxstc1998.jpg"},{"name":"Harley-Davidson Fat Boy Lo","rarity":"uncommon","id":"harley-davidson-fat-boy-lo","subtitle":"American Cruisers","details":"The Fat Boy Lo dropped the Fat Boy's seat to one of the lowest in Harley's range, with blacked-out finishes replacing the original's brightwork.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/FLSTFB_Fat_Boy.jpg/1280px-FLSTFB_Fat_Boy.jpg"},{"name":"Harley-Davidson Ultra Limited","rarity":"uncommon","id":"harley-davidson-ultra-limited","subtitle":"American Cruisers","details":"The Ultra Limited tops Harley's touring range with a Tour-Pak top box, batwing fairing, hard luggage and every long-distance comfort in the catalog.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Paris_-_Salon_de_la_moto_2011_-_Harley-Davidson_-_FLHTK_Electra_Glide_Ultra_Limited_-_001.jpg/1280px-Paris_-_Salon_de_la_moto_2011_-_Harley-Davidson_-_FLHTK_Electra_Glide_Ultra_Limited_-_001.jpg"},{"name":"Harley-Davidson Softail Slim S","rarity":"uncommon","id":"harley-davidson-softail-slim-s","subtitle":"American Cruisers","details":"The Softail Slim S added the Screamin' Eagle 110 engine and military-inspired olive paint to the Slim's postwar bobber formula, star badge included.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a0/A_1800cc_Harley_Davidson_Softail_FLSS_-_geograph.org.uk_-_5922653.jpg"},{"name":"Harley-Davidson Freewheeler","rarity":"uncommon","id":"harley-davidson-freewheeler","subtitle":"American Cruisers","details":"The Freewheeler is Harley's minimalist trike, a stripped hot-rod stance on three wheels with a small trunk and big-twin torque underneath.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/Harley-Davidson_Freewheeler%2C_107_ci_%281%29.jpg/1280px-Harley-Davidson_Freewheeler%2C_107_ci_%281%29.jpg"},{"name":"Royal Enfield Bullet 500","rarity":"uncommon","id":"royal-enfield-bullet-500","subtitle":"British & European Classics","details":"The Bullet's long-stroke 499cc single delivered gentle, thumping power through decades of continuous development in British and Indian hands.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Royal_Enfield_Bullet_500_G5.jpg/960px-Royal_Enfield_Bullet_500_G5.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Triumph Tiger 100","rarity":"uncommon","id":"triumph-tiger-100","subtitle":"British & European Classics","details":"The Tiger 100 was the sporting 498cc version of Edward Turner's Speed Twin, a light, quick twin raced successfully on both sides of the Atlantic.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Triumph_Tiger_100_%281952%29.jpg/960px-Triumph_Tiger_100_%281952%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BSA A10 Golden Flash","rarity":"uncommon","id":"bsa-a10-golden-flash","subtitle":"British & European Classics","details":"BSA's 646cc A10 twin anchored the Golden Flash, a sturdy tourer equally at home hauling a sidecar across post-war Britain.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/BSA_A10_Golden_Flash_%281960%29_-_30405313581.jpg/960px-BSA_A10_Golden_Flash_%281960%29_-_30405313581.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Norton Dominator","rarity":"uncommon","id":"norton-dominator","subtitle":"British & European Classics","details":"The Dominator spread the featherbed frame's fine handling to a 497cc twin, and its Model 88 became the benchmark British sports roadster.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/1957_Norton_Dominator.jpg/960px-1957_Norton_Dominator.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ducati Darmah","rarity":"uncommon","id":"ducati-darmah","subtitle":"British & European Classics","details":"The Darmah wrapped Ducati's 864cc bevel-drive V-twin in a relaxed sports-tourer, trading clip-ons for comfort while keeping its character.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Ducati_900_Darmah_SD_1977.jpg/960px-Ducati_900_Darmah_SD_1977.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ducati Paso 750","rarity":"uncommon","id":"ducati-paso-750","subtitle":"British & European Classics","details":"Tamburini's Paso hid its 748cc twin under fully enclosed bodywork — controversial in 1986, and a milestone in motorcycle styling.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/1988_Ducati_750_Paso_Limited_Edition.jpg/960px-1988_Ducati_750_Paso_Limited_Edition.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Moto Guzzi V50","rarity":"uncommon","id":"moto-guzzi-v50","subtitle":"British & European Classics","details":"The small-block V50 shrank Guzzi's transverse V-twin formula to 490cc, keeping shaft drive and linked brakes in a light, novice-friendly package.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Moto_Guzzi_V50_III_brown_2.jpg/960px-Moto_Guzzi_V50_III_brown_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Triumph Speed Triple 900","rarity":"uncommon","id":"triumph-speed-triple-900","subtitle":"British & European Classics","details":"Hinckley's original Speed Triple stripped the Daytona's 885cc triple into a black, single-headlamp streetfighter that launched a dynasty.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/Triumph_Speed_Triple_T300b_1994_sideview_right.jpg/960px-Triumph_Speed_Triple_T300b_1994_sideview_right.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Royal Enfield Continental GT 650","rarity":"uncommon","id":"royal-enfield-continental-gt-650","subtitle":"British & European Classics","details":"The Continental GT pairs Enfield's 648cc twin with clip-on bars, rear-set pegs and a sculpted seat hump in authentic cafe racer fashion.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Royal_Enfield_Continental_GT_650_%281%29.jpg/960px-Royal_Enfield_Continental_GT_650_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"AJS Model 31","rarity":"uncommon","id":"ajs-model-31","subtitle":"British & European Classics","details":"The Model 31 was AMC's 646cc twin answer to rival British roadsters, sharing its running gear with the Matchless G12 from the same factory.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/AJS_Model_31_%281960%29.jpg/960px-AJS_Model_31_%281960%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Velocette MAC","rarity":"uncommon","id":"velocette-mac","subtitle":"British & European Classics","details":"Velocette's 349cc overhead-cam single brought race-bred design to ordinary riders, and MACs served despatch duty throughout the war years.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/Velocette_MAC_350.jpg/960px-Velocette_MAC_350.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ariel Red Hunter","rarity":"uncommon","id":"ariel-red-hunter","subtitle":"British & European Classics","details":"Val Page's Red Hunter singles were sporting yet practical mounts, and the 497cc NH model became a favourite with clubman competitors.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/Nationale_oldtimerdag_Zandvoort_2010%2C_Ariel_Red_Hunter-1.JPG/960px-Nationale_oldtimerdag_Zandvoort_2010%2C_Ariel_Red_Hunter-1.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BMW R65","rarity":"uncommon","id":"bmw-r65","subtitle":"British & European Classics","details":"The R65 shortened and lightened BMW's boxer formula with a 648cc twin, monoshock on later LS and standard models, and nimble city manners.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/BMW_R65.jpg/960px-BMW_R65.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ducati 748","rarity":"uncommon","id":"ducati-748","subtitle":"British & European Classics","details":"The 748 miniaturised the 916 formula with a revvier 748cc desmoquattro twin, the same trellis frame and identical silhouette.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Ducati_748.jpg/960px-Ducati_748.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"MV Agusta Brutale 750","rarity":"uncommon","id":"mv-agusta-brutale-750","subtitle":"British & European Classics","details":"The Brutale stripped the F4's bodywork away, leaving its 749cc radial-valve four, sculpted tank and stacked headlights fully exposed.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3f/MV_Agusta_Brutale_750S_F4_2003_01.jpg/960px-MV_Agusta_Brutale_750S_F4_2003_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Moto Guzzi Breva 750","rarity":"uncommon","id":"moto-guzzi-breva-750","subtitle":"British & European Classics","details":"The Breva brought Guzzi's 744cc small-block twin to a friendly, upright roadster with shaft drive and a low seat for everyday riding.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/Moto_Guzzi_Breva_750_-_2003.jpg/960px-Moto_Guzzi_Breva_750_-_2003.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Triumph Thunderbird 900","rarity":"uncommon","id":"triumph-thunderbird-900","subtitle":"British & European Classics","details":"Hinckley's Thunderbird revived a famous name with an 885cc triple tuned for midrange, chrome detailing and laid-back classic styling.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Triumph_Thunderbird_900_2.jpg/960px-Triumph_Thunderbird_900_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Benelli Tornado Tre 900","rarity":"uncommon","id":"benelli-tornado-tre-900","subtitle":"British & European Classics","details":"Benelli's Tornado mounted its 898cc triple's radiator under the seat with twin extractor fans, a signature no other superbike shared.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Benelli_Tornado_Tre_900-RS_%2815111445015%29.jpg/960px-Benelli_Tornado_Tre_900-RS_%2815111445015%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Aprilia RSV Mille","rarity":"uncommon","id":"aprilia-rsv-mille","subtitle":"British & European Classics","details":"Aprilia's first big superbike wrapped a 998cc Rotax V-twin in a twin-spar aluminium frame and took the fight to Ducati in World Superbikes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/2001_Aprilia_RSV_1000_Mille_1.jpg/960px-2001_Aprilia_RSV_1000_Mille_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}]});
